-- Exercise the Data API roles with real ownership and live-session fixtures.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,aud,role,is_anonymous,created_at) values('e4100001-0000-4000-8000-000000000001','notification-1@example.invalid','authenticated','authenticated',false,now());
insert into auth.sessions(id,user_id,created_at,updated_at) values('e4200000-0000-4000-8000-000000000001','e4100001-0000-4000-8000-000000000001',now(),now());
insert into public.mobile_notification_preferences(user_id) values('e4100001-0000-4000-8000-000000000001');
insert into public.mobile_push_tokens(user_id,expo_push_token,platform,is_active) values('e4100001-0000-4000-8000-000000000001','audit-inert-token-1','ios',false);
insert into public.mobile_notifications(id,user_id,type,category,title,body) values('e4300000-0000-4000-8000-000000000001','e4100001-0000-4000-8000-000000000001','generation_succeeded','generation','Audit fixture','Local only');
insert into auth.users(id,email,aud,role,is_anonymous,created_at) values('e4100002-0000-4000-8000-000000000002','notification-2@example.invalid','authenticated','authenticated',false,now());
insert into auth.sessions(id,user_id,created_at,updated_at) values('e4200000-0000-4000-8000-000000000002','e4100002-0000-4000-8000-000000000002',now(),now());
insert into public.mobile_notification_preferences(user_id) values('e4100002-0000-4000-8000-000000000002');
insert into public.mobile_push_tokens(user_id,expo_push_token,platform,is_active) values('e4100002-0000-4000-8000-000000000002','audit-inert-token-2','ios',false);
insert into public.mobile_notifications(id,user_id,type,category,title,body) values('e4300000-0000-4000-8000-000000000002','e4100002-0000-4000-8000-000000000002','generation_succeeded','generation','Audit fixture','Local only');
insert into auth.users(id,email,aud,role,is_anonymous,created_at) values('e4100003-0000-4000-8000-000000000003','notification-3@example.invalid','authenticated','authenticated',true,now());
insert into auth.sessions(id,user_id,created_at,updated_at) values('e4200000-0000-4000-8000-000000000003','e4100003-0000-4000-8000-000000000003',now(),now());
insert into public.mobile_notification_preferences(user_id) values('e4100003-0000-4000-8000-000000000003');
insert into public.mobile_push_tokens(user_id,expo_push_token,platform,is_active) values('e4100003-0000-4000-8000-000000000003','audit-inert-token-3','ios',false);
insert into public.mobile_notifications(id,user_id,type,category,title,body) values('e4300000-0000-4000-8000-000000000003','e4100003-0000-4000-8000-000000000003','generation_succeeded','generation','Audit fixture','Local only');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e4100001-0000-4000-8000-000000000001","role":"authenticated","session_id":"e4200000-0000-4000-8000-000000000001","is_anonymous":false}',true);
select ok(public.current_identity_is_active(),'owner has a live session');
select is((select count(*) from public.mobile_notifications),1::bigint,'mobile_notifications: reads only own row');
with changed as (update public.mobile_notifications set is_read=true where user_id='e4100002-0000-4000-8000-000000000002' returning user_id) select is((select count(*) from changed),0::bigint,'mobile_notifications: foreign update affects no rows');
select is((select count(*) from public.mobile_notification_preferences),1::bigint,'mobile_notification_preferences: reads only own row');
with changed as (update public.mobile_notification_preferences set updated_at=now() where user_id='e4100002-0000-4000-8000-000000000002' returning user_id) select is((select count(*) from changed),0::bigint,'mobile_notification_preferences: foreign update affects no rows');
select is((select count(*) from public.mobile_push_tokens),1::bigint,'mobile_push_tokens: reads only own row');
with changed as (update public.mobile_push_tokens set updated_at=now() where user_id='e4100002-0000-4000-8000-000000000002' returning user_id) select is((select count(*) from changed),0::bigint,'mobile_push_tokens: foreign update affects no rows');
select lives_ok($$ update public.mobile_notifications set is_read=true where id='e4300000-0000-4000-8000-000000000001' $$,'owner can mark a notification read');
select throws_ok($$ update public.mobile_notifications set title='forged' $$,'42501',null,'notification content cannot be forged');
select throws_ok($$ delete from public.mobile_notifications $$,'42501',null,'notification history cannot be deleted directly');
select throws_ok($$ insert into public.mobile_notifications(user_id,type,category,title,body) values('e4100001-0000-4000-8000-000000000001','generation_succeeded','generation','forged','forged') $$,'42501',null,'notifications cannot be fabricated');
select lives_ok($$ update public.mobile_notification_preferences set push_enabled=false where user_id='e4100001-0000-4000-8000-000000000001' $$,'owner can change preferences');
select lives_ok($$ insert into public.mobile_push_tokens(user_id,expo_push_token,platform,is_active) values('e4100001-0000-4000-8000-000000000001','audit-new-inert-token','android',false) $$,'registered owner can register token');
select throws_ok($$ insert into public.mobile_push_tokens(user_id,expo_push_token,platform,is_active) values('e4100002-0000-4000-8000-000000000002','audit-foreign-inert-token','android',false) $$,'42501',null,'cannot register a token for another user');
select throws_ok($$ update public.mobile_push_tokens set user_id='e4100002-0000-4000-8000-000000000002' where user_id='e4100001-0000-4000-8000-000000000001' $$,'42501',null,'cannot transfer token ownership directly');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e4100003-0000-4000-8000-000000000003","role":"authenticated","session_id":"e4200000-0000-4000-8000-000000000003","is_anonymous":false}',true);
select ok(public.current_identity_is_active(),'guest has a live session so active gate alone cannot reject it');
select is(public.current_identity_is_registered(),false,'auth row is authoritative even with a false anonymous claim');
select is((select count(*) from public.mobile_notifications),0::bigint,'mobile_notifications: guest cannot read even own historical rows');
with changed as (update public.mobile_notifications set is_read=true returning user_id) select is((select count(*) from changed),0::bigint,'mobile_notifications: guest cannot update own rows');
select is((select count(*) from public.mobile_notification_preferences),0::bigint,'mobile_notification_preferences: guest cannot read even own historical rows');
with changed as (update public.mobile_notification_preferences set updated_at=now() returning user_id) select is((select count(*) from changed),0::bigint,'mobile_notification_preferences: guest cannot update own rows');
select is((select count(*) from public.mobile_push_tokens),0::bigint,'mobile_push_tokens: guest cannot read even own historical rows');
with changed as (update public.mobile_push_tokens set updated_at=now() returning user_id) select is((select count(*) from changed),0::bigint,'mobile_push_tokens: guest cannot update own rows');
select throws_ok($$ insert into public.mobile_push_tokens(user_id,expo_push_token,platform,is_active) values('e4100003-0000-4000-8000-000000000003','audit-guest-inert-token','ios',false) $$,'42501',null,'guest cannot bypass registration API');
select throws_ok($$ insert into public.mobile_notification_preferences(user_id) values('e4100003-0000-4000-8000-000000000003') on conflict(user_id) do update set push_enabled=false $$,'42501',null,'guest cannot upsert preferences directly');
reset role;
delete from auth.sessions where id='e4200000-0000-4000-8000-000000000001';
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e4100001-0000-4000-8000-000000000001","role":"authenticated","session_id":"e4200000-0000-4000-8000-000000000001","is_anonymous":false}',true);
select is((select count(*) from public.mobile_notifications),0::bigint,'mobile_notifications: revoked session cannot read');
with changed as (update public.mobile_notifications set is_read=false returning user_id) select is((select count(*) from changed),0::bigint,'mobile_notifications: revoked session cannot update');
select is((select count(*) from public.mobile_notification_preferences),0::bigint,'mobile_notification_preferences: revoked session cannot read');
with changed as (update public.mobile_notification_preferences set updated_at=now() returning user_id) select is((select count(*) from changed),0::bigint,'mobile_notification_preferences: revoked session cannot update');
select is((select count(*) from public.mobile_push_tokens),0::bigint,'mobile_push_tokens: revoked session cannot read');
with changed as (update public.mobile_push_tokens set updated_at=now() returning user_id) select is((select count(*) from changed),0::bigint,'mobile_push_tokens: revoked session cannot update');
reset role;
update auth.users set banned_until=now()+interval '1 hour' where id='e4100002-0000-4000-8000-000000000002';
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e4100002-0000-4000-8000-000000000002","role":"authenticated","session_id":"e4200000-0000-4000-8000-000000000002","is_anonymous":false}',true);
select is((select count(*) from public.mobile_notifications),0::bigint,'mobile_notifications: banned owner cannot read');
select is((select count(*) from public.mobile_notification_preferences),0::bigint,'mobile_notification_preferences: banned owner cannot read');
select is((select count(*) from public.mobile_push_tokens),0::bigint,'mobile_push_tokens: banned owner cannot read');
reset role;
set local role anon;
select throws_ok($$ select * from public.mobile_notifications $$,'42501',null,'mobile_notifications: unauthenticated read denied');
select throws_ok($$ select * from public.mobile_notification_preferences $$,'42501',null,'mobile_notification_preferences: unauthenticated read denied');
select throws_ok($$ select * from public.mobile_push_tokens $$,'42501',null,'mobile_push_tokens: unauthenticated read denied');
reset role;
set local role service_role;
select is((select count(*) from public.mobile_notifications where user_id='e4100003-0000-4000-8000-000000000003'),1::bigint,'mobile_notifications: service can maintain historical guest rows');
select is((select count(*) from public.mobile_notification_preferences where user_id='e4100003-0000-4000-8000-000000000003'),1::bigint,'mobile_notification_preferences: service can maintain historical guest rows');
select is((select count(*) from public.mobile_push_tokens where user_id='e4100003-0000-4000-8000-000000000003'),1::bigint,'mobile_push_tokens: service can maintain historical guest rows');
reset role;
select * from finish();
rollback;
